#include <windows.h>
#include <tlhelp32.h>
#include <dbghelp.h>
#include <iostream>
#pragma comment(lib,"dbghelp.lib")
int main(int argc,char**argv){if(argc!=2)return 2;DWORD pid=atoi(argv[1]);HANDLE p=OpenProcess(PROCESS_QUERY_INFORMATION|PROCESS_VM_READ,FALSE,pid);if(!p)return 3;SymSetOptions(SYMOPT_DEFERRED_LOADS|SYMOPT_LOAD_LINES);if(!SymInitialize(p,"C:\\MotorRock\\game-debug",TRUE))return 4;HANDLE snapshot=CreateToolhelp32Snapshot(TH32CS_SNAPTHREAD,0);THREADENTRY32 e={sizeof(e)};if(Thread32First(snapshot,&e))do{if(e.th32OwnerProcessID!=pid)continue;HANDLE t=OpenThread(THREAD_GET_CONTEXT|THREAD_SUSPEND_RESUME|THREAD_QUERY_INFORMATION,FALSE,e.th32ThreadID);if(!t)continue;if(SuspendThread(t)==(DWORD)-1){CloseHandle(t);continue;}CONTEXT c={0};c.ContextFlags=CONTEXT_FULL;if(GetThreadContext(t,&c)){STACKFRAME64 f={0};f.AddrPC.Offset=c.Eip;f.AddrPC.Mode=AddrModeFlat;f.AddrStack.Offset=c.Esp;f.AddrStack.Mode=AddrModeFlat;f.AddrFrame.Offset=c.Ebp;f.AddrFrame.Mode=AddrModeFlat;std::cout<<"thread "<<e.th32ThreadID<<'\n';for(unsigned i=0;i<64;++i){char b[sizeof(SYMBOL_INFO)+2048]={0};SYMBOL_INFO*s=(SYMBOL_INFO*)b;s->SizeOfStruct=sizeof(SYMBOL_INFO);s->MaxNameLen=2047;DWORD64 d=0;IMAGEHLP_MODULE64 m={sizeof(m)};SymGetModuleInfo64(p,f.AddrPC.Offset,&m);std::cout<<i<<" "<<std::hex<<f.AddrPC.Offset<<std::dec<<" "<<m.ModuleName<<"!";if(SymFromAddr(p,f.AddrPC.Offset,&d,s))std::cout<<s->Name<<"+"<<d;std::cout<<'\n';if(!StackWalk64(IMAGE_FILE_MACHINE_I386,p,t,&f,&c,0,SymFunctionTableAccess64,SymGetModuleBase64,0))break;}}ResumeThread(t);CloseHandle(t);}while(Thread32Next(snapshot,&e));CloseHandle(snapshot);SymCleanup(p);CloseHandle(p);return 0;}
